```repl
# Inspect files and attempt to read the SQLite DB
import os, sqlite3, binascii, textwrap

files = ["/app/main.db", "/app/main.db-wal"]
info = {}
for f in files:
    try:
        st = os.stat(f)
        with open(f, "rb") as fh:
            head = fh.read(512)
        info[f] = {
            "size": st.st_size,
            "head_hex": binascii.hexlify(head).decode('ascii')
        }
    except Exception as e:
        info[f] = {"error": str(e)}

print("FILE INFO:")
for f, v in info.items():
    print(f"\n== {f} ==\n{v}\n")

# Try to open the SQLite DB and list tables / rows
print("ATTEMPTING SQLITE ACCESS:")
try:
    conn = sqlite3.connect("/app/main.db")
    cur = conn.cursor()
    try:
        cur.execute("PRAGMA journal_mode;")
        print("PRAGMA journal_mode ->", cur.fetchone())
    except Exception as e:
        print("PRAGMA journal_mode error:", e)
    try:
        cur.execute("SELECT name FROM sqlite_master WHERE type='table';")
        tables = [r[0] for r in cur.fetchall()]
        print("TABLES:", tables)
        for t in tables:
            try:
                cur.execute(f"SELECT COUNT(*) FROM {t};")
                cnt = cur.fetchone()[0]
                print(f"TABLE {t}: COUNT = {cnt}")
                cur.execute(f"SELECT * FROM {t} ORDER BY id;")
                rows = cur.fetchall()
                print(f"ROWS from {t}:")
                for r in rows:
                    print(r)
            except Exception as e:
                print(f"Error reading table {t}:", e)
    except Exception as e:
        print("Error listing tables:", e)
    conn.close()
except Exception as e:
    print("Error opening /app/main.db with sqlite3:", e)
```

