# Scan REPL variables and a few known history vars for long hex-like runs or WAL indicators.
import re, itertools, binascii

candidates = []

vars_to_check = list(globals().items()) + [(n, globals().get(n)) for n in ("history","history_0","context_0","context")]
seen = set()
for name, val in vars_to_check:
    if name in seen or val is None:
        continue
    seen.add(name)
    txt = None
    if isinstance(val, bytes):
        try:
            txt = val.decode('utf-8', errors='replace')
        except:
            txt = str(val)
    else:
        txt = str(val)
    # look for "SQLite WAL" or "head_hex" or long hex runs
    if "SQLite WAL" in txt or "head_hex" in txt or "main.db-wal" in txt:
        candidates.append((name, "keyword", txt[:400]))
    # find long hex runs >= 128 chars
    for m in re.finditer(r'([0-9a-fA-F]{128,})', txt):
        hexrun = m.group(1)
        start = max(0, m.start()-80)
        end = min(len(txt), m.end()+80)
        candidates.append((name, f"hexlen={len(hexrun)}", txt[start:end]))
        # only capture first few per var
        break

print("Inspected variables. Found candidate snippets (up to 10):", len(candidates))
for i, (name, tag, snippet) in enumerate(itertools.islice(candidates, 10), 1):
    print(f"\n--- Candidate {i} ---\nVariable: {name}\nTag: {tag}\nSnippet (len {len(snippet)}):\n{snippet}\n")

