# Search filesystem (bounded) for files whose first 64 bytes contain 'WAL' or 'SQLite'.
# Skip very large files and unreadable paths to avoid OOM/permission issues.
import os, sys

candidates = []
def check_file(path):
    try:
        st = os.stat(path)
        # skip directories, sockets, etc.
        if not os.path.isfile(path):
            return
        # skip huge files (>1MB) to be safe
        if st.st_size > 2_000_000:
            return
        with open(path, "rb") as fh:
            head = fh.read(64)
        if b"WAL" in head or b"SQLite" in head:
            candidates.append((path, st.st_size, head[:64]))
    except Exception:
        return

# Walk a limited set of likely directories
roots = ["/app", "/tmp", "/var", "/root", "/home", "/usr", "/etc", "/opt"]
seen = set()
for root in roots:
    if not os.path.exists(root):
        continue
    for dirpath, dirnames, filenames in os.walk(root):
        for fn in filenames:
            path = os.path.join(dirpath, fn)
            if path in seen:
                continue
            seen.add(path)
            check_file(path)

# Also check current working directory and its parents
for path in [os.getcwd()] + [os.path.abspath(p) for p in os.listdir("/")]:
    pass

print("Found candidate files with 'WAL' or 'SQLite' in head (path, size):")
for p, s, head in candidates:
    preview = head.decode("ascii", errors="replace")
    print(f"{p}  size={s}\n head_preview={preview}\n")
if not candidates:
    print("No candidate WAL/SQLite headers found in searched locations.")
