def read_varint(buf, off):
    val = 0
    i = 0
    while i < 8:
        if off + i >= len(buf):
            raise IndexError("varint out of range")
        b = buf[off+i]
        val = (val << 7) | (b & 0x7F)
        if not (b & 0x80):
