from pathlib import Path
import binascii, struct, json

data = Path("/app/main.db").read_bytes()
page_size = 4096
pages = {1: data[0:page_size], 2: data[page_size:page_size*2]}

def read_varint(buf, off):
    val = 0
    i = 0
    while i < 8:
        if off + i >= len(buf):
            raise IndexError("varint out of range")
        b = buf[off+i]
        val = (val << 7) | (b & 0x7F)
        if not (b & 0x80):
            return val, i+1
        i += 1
    b = buf[off+8]
    val = (val << 8) | b
    return val, 9

def parse_serial_type(buf, off, stype):
    if stype == 0:
        return None, 0
    if stype == 1:
        return struct.unpack(">b", buf[off:off+1])[0], 1
    if stype == 2:
        return int.from_bytes(buf[off:off+2], "big", signed=True), 2
    if stype == 3:
        b = buf[off:off+3]; v = int.from_bytes(b, "big", signed=False)
        if v & (1<<23): v -= (1<<24)
        return v, 3
    if stype == 4:
        return int.from_bytes(buf[off:off+4], "big", signed=True), 4
    if stype == 5:
        return int.from_bytes(buf[off:off+6], "big", signed=True), 6
    if stype == 6:
        return int.from_bytes(buf[off:off+8], "big", signed=True), 8
    if stype == 7:
        return struct.unpack(">d", buf[off:off+8])[0], 8
    if stype == 8:
        return 0, 0
    if stype == 9:
        return 1, 0
    if stype >= 12:
        if stype % 2 == 0:
            size = (stype - 12)//2
            return buf[off:off+size], size
        else:
            size = (stype - 13)//2
            s = buf[off:off+size].decode("utf-8", errors="replace")
            return s, size
    return None, 0

def inspect_page(page_bytes, page_num):
    out = {"page": page_num}
    hdr_off = 100 if page_num==1 else 0
    if len(page_bytes) < hdr_off+8:
        out["error"] = "page too small"
        return out
    ptype = page_bytes[hdr_off]
    cell_count = int.from_bytes(page_bytes[hdr_off+3:hdr_off+5], "big")
    cell_content_area = int.from_bytes(page_bytes[hdr_off+5:hdr_off+7], "big")
    out.update({"page_type": ptype, "cell_count": cell_count, "cell_content_area": cell_content_area, "cells": []})
    cellptr_off = hdr_off + 8
    for i in range(cell_count):
        ptr = cellptr_off + i*2
        if ptr+2 > len(page_bytes):
            out["cells"].append({"index": i, "error": "cellptr OOB"})
            continue
        cell_offset = int.from_bytes(page_bytes[ptr:ptr+2], "big")
        cell_info = {"index": i, "cell_offset": cell_offset}
        if cell_offset==0 or cell_offset>=len(page_bytes):
            out["cells"].append(cell_info); continue
        try:
            payload_size, l1 = read_varint(page_bytes, cell_offset)
            rowid, l2 = read_varint(page_bytes, cell_offset + l1)
            payload_off = cell_offset + l1 + l2
            payload = page_bytes[payload_off: payload_off + payload_size]
            cell_info.update({"payload_size": payload_size, "rowid": rowid, "payload_off": payload_off, "payload_hex": payload.hex()[:400]})
            # parse record header
            try:
                header_len, hl = read_varint(payload, 0)
                cell_info["record_header_len"] = header_len
                serials = []
                idx = hl
                st_list = []
                while idx < header_len and idx < len(payload):
                    st, stl = read_varint(payload, idx)
                    st_list.append(st)
                    idx += stl
                cell_info["serial_types"] = st_list
                # parse column values
                col_off = header_len
                vals = []
                raw_vals = []
                for st in st_list:
                    v, vlen = parse_serial_type(payload, col_off, st)
                    raw_vals.append({"stype": st, "raw": (v if not isinstance(v, bytes) else v.hex()), "value": v})
                    vals.append(v)
                    col_off += vlen
                cell_info["values"] = raw_vals
            except Exception as e:
                cell_info["record_parse_error"] = str(e)
        except Exception as e:
            cell_info["cell_parse_error"] = str(e)
        out["cells"].append(cell_info)
    return out

inspections = []
for pnum in (1,2):
    inspections.append(inspect_page(pages[pnum], pnum))

print(json.dumps(inspections, indent=2)[:10000])
